insert into public.production_polymer_injection_monthly (reporting_period_id, volume_polymer_solution_injected_m3, number_injector_wells, average_injection_pressure_psi, average_viscosity_cp, number_offset_production_wells, oil_produced_offset_wells_m3, water_produced_offset_wells_m3, gas_produced_offset_wells_m3, avg_oil_produced_offset_well_m3, average_water_cut_offset_wells_percent, wells_using_source_water)
select p.id, s.volume_polymer_solution_injected_m3, s.number_injector_wells, s.average_injection_pressure_psi, s.average_viscosity_cp, s.number_offset_production_wells, s.oil_produced_offset_wells_m3, s.water_produced_offset_wells_m3, s.gas_produced_offset_wells_m3, s.avg_oil_produced_offset_well_m3, s.average_water_cut_offset_wells_percent, s.wells_using_source_water
from source s join public.reporting_periods p on p.period_date = s.period_date
on conflict (reporting_period_id) do update set volume_polymer_solution_injected_m3=excluded.volume_polymer_solution_injected_m3, number_injector_wells=excluded.number_injector_wells, average_injection_pressure_psi=excluded.average_injection_pressure_psi, average_viscosity_cp=excluded.average_viscosity_cp, number_offset_production_wells=excluded.number_offset_production_wells, oil_produced_offset_wells_m3=excluded.oil_produced_offset_wells_m3, water_produced_offset_wells_m3=excluded.water_produced_offset_wells_m3, gas_produced_offset_wells_m3=excluded.gas_produced_offset_wells_m3, avg_oil_produced_offset_well_m3=excluded.avg_oil_produced_offset_well_m3, average_water_cut_offset_wells_percent=excluded.average_water_cut_offset_wells_percent, wells_using_source_water=excluded.wells_using_source_water, updated_at=now();
